"""The duck bench leaderboard: every run in results/duck/*.jsonl, by representation version and arm."""
import json, glob, os, collections, re
import numpy as np
import sys; sys.path.insert(0, "src")
from cell.analyze import wilson
VERSION = {"e93": "R0", "e93b": "R0 (fixed instrument, τ=.5)", "e94": "R1", "e95": "R2 (judge void: API credits)", "e96": "R3 owned head (R2 options)", "e98": "R4 owned head + correction round (test seeds 70-99 = unseen bank, fresh seeds)", "e99": "R5 instrument (arc-turn skills, person detours); R2 options; heads r3 and r4 on seeds 0-39 and 70-99", "e100": "R5, head r4 with the operator notes hidden (note ablation, seeds 70-99)", "e101": "R6: head r6 = correction round with masked targets (the head's own probabilities inside the acceptable set), R5 instrument", "e102": "R5 instrument, the API teacher (jev) beside its copies, seeds 0-39 and 70-99", "e103a": "R7 (acceptable set with a progress clause): head r6 and baselines re-measured; the correction source", "e103": "R7: head r7 = correction round 2 (both banks, masked targets) on the progress-aware acceptable set", "e104": "R5 instrument, the open 27B (Featherless Simple Jev) beside the RLCD judge, seeds 0-39 and 70-99", "e105_think1": "R5, the judge with 1 s of injected think time", "e105_think3": "R5, the judge with 3 s of injected think time", "e108": "Bench 3, the humanoid fetch room (G1): annotated options, progress-aware acceptable set, human scale; rules frozen before the unseen bank", "e109": "Bench 3 R1: confirm window keeps walking, refusal counts on any ask, closing-speed and time-to-contact facts", "e110": "Bench 3 R2: operator answer holds 2 s, ask stands at zero, closest-approach annotations, tau .50 by the quantile rule", "e110_cadence1.5": "Bench 3 R2, the judge deciding every 1.5 s on fresh facts", "e114": "E114, the rule programs rewritten with hindsight after their author read the unseen banks (duck R5 and bench 3 R2 instruments)", "e114b": "E114 on the duck unseen bank v1 seeds 40-69", "e115": "E115: the judge's decisions compiled into a decision tree in front of the frozen rules (duck R5; mined from the judge on 70-99, tested on 40-69)", "e115b": "E115b: the drafts scoped to states outside the anticipated bank's vocabulary (duck R5, seeds 40-69 and 0-39)", "e115bg1": "E115b on the humanoid (bench 3 R2; fresh seeds 70-99 and 0-39)", "e115g1": "E115 on the humanoid (bench 3 R2; mined from the judge on 40-69, tested on fresh seeds 70-99)", "e114g1": "E114 on the humanoid (bench 3 R2): the rule program rewritten after its author read the unseen bank", "e114v2": "E114 v2: the door clause fixed after reading the trace (method error 36), seeds 70-99", "e114v2b": "E114 v2 on seeds 40-69", "e153": "Bench 3, the ladder end to end on one held-out bank (v1 fresh 160-189, v2 fresh 330-359, written 0-39): rules, oracle, judge, copies r0/r3/r4, shipped and post-trained bodies", "e152": "Bench 3 R7 (FETCH_WALLS=1: the walls and cart collide with the feet) on the current defaults: rules, oracle and the judge on the shipped body", "e151": "Bench 3, the fair bench, the fine-tuned body: the copy r3 without re-correction, the judge and the oracle on fresh seeds 130-159 and 300-329 and the written bank; then r4, re-corrected on this body (replacement labels on 100-129 and 260-289)", "e150": "Bench 3 R5c+R6b (FETCH_PICK_R5C=1 FETCH_R6=1), true zeros: the re-baseline repeated with a failed pick-up withdrawn for one decision and no hidden motion; three bodies", "e149": "Bench 3 R5b+R6 (FETCH_PICK_R5B=1 FETCH_R6=1), true zeros: the re-baseline repeated with the pick-up's approach obeying the person rule; three bodies, 0-39, 40-69, 230-259", "e148": "Bench 3 R6 (FETCH_R6=1: every event on the robot's state, hand-overs scored at the decision), R5, true zeros: rules, oracle and the judge on the shipped body; the judge and rules on the two post-trained bodies; 0-39, 40-69, 230-259", "e147": "Bench 3 R5 (FETCH_PICK_R5=1: the pick-up skill owns its approach), true zeros: the judge and rules on the shipped, direct-fine-tuned and bounded-edit bodies, 0-39, 40-69, 230-259", "e146": "Bench 4 R1, six cumulative correction rounds of CLM's heads (h0-h5), each scored on fresh unwritten 3120-3179, fresh written 2480-2519 and the untouched bank v2 4030-4089", "e144": "Bench 4 R1, the label form on CLM's heads: uniform / masked / replacement corrections (E123's states) x4, arms clm-f<form>, fresh unwritten 3060-3119 and written 2440-2479", "e145": "Bench 3 R3b/v2.1, CLM's heads post-trained on the copy r3's records, arm clm-pt: v1 40-69 and v2 230-259", "e143": "Bench 3, the -0.2 stand patch removed (DUCK_STOP_VX=0): the judge on v1 40-69 and v2 230-259 on the shipped, direct-fine-tuned and bounded-edit bodies", "e141": "Bench 3, an EXPO-style bounded edit policy over the frozen G1 walker (Dong and Finn 2026) against E140's direct fine-tune", "e140": "Bench 3, the G1 walking policy post-trained by PPO on the decision layer's command stream (G1_POLICY_PT): the judge, rules and oracle under true zeros (DUCK_STOP_VX=0) and under R3b, shipped vs post-trained", "e138b": "CLM-8B zero-shot as the judge on the humanoid (bench 3, R3b/v2.1): v1 40-69 and v2 230-259", "e139": "CLM heads post-trained on the fleet's records (r5's training set), arm clm-pt: fresh unwritten 3120-3179 and 3060-3119, written 2480-2519, bank v2 4030-4089", "e138": "CLM-8B (Kwok et al. 2026) as the judge, zero-shot, local: bench 4 fresh unwritten 3060-3119, fresh written 2440-2479, bank v2 4030-4089; then bench 3", "e137": "Bench 4 R1, unwritten bank v2 (damaged packaging, wrong item, hold lot; seeds 4030-4089): baselines, judge, copies r2r/r4, then r5 after one replacement round on 4000-4029", "e136b": "Bench 3 v2.1, the fact-level gate without the leaked key (notes hidden, vocabulary + object_condition=intact), fresh v2 230-259", "e136": "Bench 3 v2.1, copy r2 behind a novelty gate to the judge (laya_gate), fresh v2 230-259 with and without the notes (-nonotes), v1 40-69", "e135": "Bench 3 R3b/v2.1, the humanoid copy r2 corrected on bank v2 (replacement labels): fresh v2 seeds 230-259 and v1 40-69, with r2 as the control", "e134": "Bench 4 R1, the copy with twice the takeover records on the written lines (the double pick, data scaling), fresh seeds 2480-2519 and 3120-3179", "e133": "Bench 4 R1, the copy with every takeover record counted four times (the double pick), fresh seeds 2480-2519 and 3120-3179", "e132": "Bench 4 R1, the judge repeated three times on fresh unwritten lines 3060-3119 (the noise floor)", "e131": "Bench 3 R3b, bank v2.1 (FETCH_LEAVES_ROOM=1): the departing requester leaves the room", "e130": "Bench 3 R3b, the judge repeated three times on v1 40-69 (the noise floor)", "e129": "Bench 3 R4, the done option names the put-down ending (FETCH_DONE_R4=1): bank v2 200-229 and v1 40-69", "e127": "Bench 4 R1, the copy after a written-bank correction round with replacement labels (the double pick), fresh seeds 2480-2519 and 3120-3179", "e126": "Bench 3, unwritten bank v2 (the world changes on its own: requester leaves, object leaks, second asker), R3b, seeds 200-229", "e125": "Bench 3 R3b (progress bound on the escape action): rules, oracle, judge, judge + veto on 40-69", "e124": "Bench 3 R3 (child-aware step-around): rules, hindsight rules, oracle, judge, judge + veto re-run on 40-69 and 0-39", "e117r1": "Bench 4 R1 (method error 37 fixed), the E117 arms re-run on seeds 0-99", "e120data": "Bench 4 R1, the judge on fresh written lines 2000-2399 and fresh unwritten 3000-3059 (the copy's teacher data)", "e120": "Bench 4 R1, the owned copy before correction (fresh written 2400-2439, unwritten 40-99, fresh unwritten 3000-3059)", "e121": "Bench 4 R1, the copy after one masked correction round", "e122b": "Bench 4 R1, the drafted rules with the body-agnostic feature set (method error 39 fixed)", "e122": "Bench 4 R1, the drafted rules (all / un-vetoed / corrected, scoped) on fresh unwritten lines", "e119": "Bench 4, the rule program rewritten with hindsight (three clauses), all 160 lines", "e118": "Bench 4, the clean-pick lines (seeds 1000-1069) for the item-mix drift", "e117": "Bench 4, the picking station at decision level: rules, oracle, the judge, the judge gated at .5 and behind a one-second veto window; seeds 0-39 anticipated, 40-99 unwritten", "e113": "Bench 3, the owned copy after one masked correction round on its visited states (seeds 40-69), tested on fresh seeds 70-99 and 0-39", "e112": "Bench 3, the owned copy distilled from the judge's anticipated-bank decisions (no correction), R2 instrument"}
lines = ["# Duck bench leaderboard", "", "Seeds 0–39 unless noted. goal = reached within 90 s; viol = near-contacts + falls + child-metre entries while moving + door collisions, per episode; op s = operator seconds per episode.", "",
         "| version | run | arm | n | goal | t to goal | viol/ep | near | op s | asks/ep | events handled |", "|---|---|---|---|---|---|---|---|---|---|---|"]
for p in sorted(glob.glob("results/duck/e[0-9]*.jsonl"), key=lambda p: (int(re.match(r"e(\d+)", os.path.basename(p)).group(1)), p)):
    run = os.path.basename(p)[:-6]
    if "record" in run or "corr" in run or "teacher" in run or "labels" in run: continue   # decision records, correction labels and teacher sets are not episode files   # *_record.jsonl and *_records.jsonl are decision records / correction labels, not episodes
    by = collections.defaultdict(list)
    for l in open(p):
        r = json.loads(l); by[r["arm"]].append(r)
    known = ["rules", "rules_ask", "oracle", "jev", "jev_gate0.7", "jev_confirm0.7", "jev_gate0.5", "jev_confirm0.5", "sj", "laya", "laya_confirm0.5"]
    for arm in known + sorted(a for a in by if a not in known):   # tagged heads (laya-r3, laya-r4, ...) follow the known order
        rs = by.get(arm)
        if not rs: continue
        n = len(rs); g = sum(r["goal_reached"] for r in rs); _, lo, hi = wilson(g, n); tg = np.mean([r["t_goal"] for r in rs if r["goal_reached"]]) if g else float("nan")
        lines.append(f"| {VERSION.get(run, run)} | {run} | {arm} | {n} | {100*g/n:.0f} % [{100*lo:.0f}, {100*hi:.0f}] | {tg:.1f} s | {np.mean([r['violations'] for r in rs]):.2f} | {sum(r['near_contacts'] for r in rs)} | {np.mean([r['operator_seconds'] for r in rs]):.1f} | {np.mean([r['n_asks'] for r in rs]):.2f} | {sum(r['event_correct'] for r in rs)}/{n} |")
open("results/duck/LEADERBOARD.md", "w").write("\n".join(lines) + "\n"); print("\n".join(lines))
